		return blankNoteArchiveRule(t, store, id, "d-stable-defect", " \n\t ")
	}
	corruptBefore, mutatedBefore := corruptSide(beforeReport.ReportID)
	corruptAfter, mutatedAfter := corruptSide(afterReport.ReportID)

	cases := []struct {
		name   string
		before string
		after  string
		keepID string
		keep   []byte
	}{
		{"second report corrupt", beforeReport.ReportID, corruptAfter, corruptAfter, mutatedAfter},
		{"first report corrupt", corruptBefore, afterReport.ReportID, corruptBefore, mutatedBefore},
		{"both corrupt", corruptBefore, corruptAfter, corruptBefore, mutatedBefore},
	}
